"""Reference data: cipher suites and named groups (generated by tools/build_data.py)."""

from __future__ import annotations

import json
from dataclasses import dataclass
from functools import cache
from importlib import resources

from cipheraudit.wire.constants import ProtocolVersion


@dataclass(frozen=True)
class CipherSuite:
    code: int
    iana: str
    openssl: str | None
    protocols: tuple[ProtocolVersion, ...]
    kx: str
    auth: str
    enc: str
    bits: int
    block_bits: int
    mode: str
    mac: str
    fs: bool
    aead: bool
    export: bool
    category: str

    @property
    def hex(self) -> str:
        return f"0x{self.code:04X}"


@dataclass(frozen=True)
class SSLv2Cipher:
    code: int
    name: str
    openssl: str
    enc: str
    bits: int
    export: bool


@dataclass(frozen=True)
class NamedGroup:
    id: int
    name: str
    kind: str  # ec | ffdhe | pq | pq_hybrid
    recommended: bool
    obsolete: bool


def _load(name: str) -> dict[str, object]:
    text = resources.files(__package__).joinpath(name).read_text(encoding="utf-8")
    data: dict[str, object] = json.loads(text)
    return data


@cache
def cipher_suites() -> dict[int, CipherSuite]:
    raw = _load("ciphers.json")["suites"]
    assert isinstance(raw, list)
    return {
        s["code"]: CipherSuite(
            code=s["code"], iana=s["iana"], openssl=s["openssl"],
            protocols=tuple(ProtocolVersion(p) for p in s["protocols"]),
            kx=s["kx"], auth=s["auth"], enc=s["enc"], bits=s["bits"], block_bits=s["block_bits"],
            mode=s["mode"], mac=s["mac"], fs=s["fs"], aead=s["aead"], export=s["export"], category=s["category"],
        )
        for s in raw
    }


@cache
def sslv2_ciphers() -> dict[int, SSLv2Cipher]:
    raw = _load("ciphers.json")["sslv2"]
    assert isinstance(raw, list)
    return {c["code"]: SSLv2Cipher(**c) for c in raw}


@cache
def named_groups() -> dict[int, NamedGroup]:
    raw = _load("groups.json")["groups"]
    assert isinstance(raw, list)
    return {g["id"]: NamedGroup(**g) for g in raw}


# Key exchanges a server only negotiates with out-of-band setup (pre-shared keys, Kerberos, SRP).
# Offering them is harmless but they crowd ClientHellos that some servers cap at 128 suites.
SPECIAL_KX = frozenset({"PSK", "KRB5", "KRB5_EXPORT", "SRP", "ECCPWD", "GOST"})


def suites_for(version: ProtocolVersion, include_special: bool = False) -> list[CipherSuite]:
    """All suites valid for `version`, strongest first (AEAD+FS before legacy)."""
    rank = {"AEAD": 0, "CBC": 1, "OTHER": 2, "3DES": 3, "RC4": 4, "DES": 5, "EXPORT": 6, "ANON": 7, "NULL": 8}
    suites = [
        s for s in cipher_suites().values()
        if version in s.protocols and (include_special or (s.kx not in SPECIAL_KX and s.auth != "PSK"))
    ]
    return sorted(suites, key=lambda s: (rank[s.category], not s.fs, -s.bits, s.code))


def suite_name(code: int) -> str:
    suite = cipher_suites().get(code)
    return suite.iana if suite else f"0x{code:04X}"
